import{_ as e,o as n,c as r,a2 as a}from"./chunks/framework.CAKCj7G0.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"服务器相关/Centos 安装Redis.md","filePath":"服务器相关/Centos 安装Redis.md"}'),p={name:"服务器相关/Centos 安装Redis.md"};function t(o,s,l,i,c,d){return n(),r("div",null,[...s[0]||(s[0]=[a(`<p>一、安装gcc依赖</p><p>由于 redis 是用 C 语言开发，安装之前必先确认是否安装 gcc 环境（gcc -v），如果没有安装，执行以下命令进行安装</p><p><strong>[root@localhost local]# yum install -y gcc</strong></p><p>二、下载并解压安装包</p><p><strong>[root@localhost local]# wget <a href="http://download.redis.io/releases/redis-6.2.6.tar.gz" target="_blank" rel="noreferrer">http://download.redis.io/releases/redis-6.2.6.tar.gz</a></strong></p><p><strong>[root@localhost local]# tar -zxvf redis-6.2.6.tar.gz</strong></p><p>三、cd切换到redis解压目录下，执行编译</p><p><strong>[root@localhost local]# cd redis-6.2.6</strong></p><p><strong>[root@localhost redis-6.2.6]# make</strong></p><p>四、安装并指定安装目录</p><p><strong>[root@localhost redis-6.2.6]# make install PREFIX=/usr/local/redis</strong></p><p>五、启动服务</p><p>5.1前台启动</p><p><strong>[root@localhost redis-6.2.6]# cd /usr/local/redis/bin/</strong></p><p><strong>[root@localhost bin]# ./redis-server</strong></p><p>5.2后台启动</p><p>从 redis 的源码目录中复制 redis.conf 到 redis 的安装目录</p><p><strong>[root@localhost bin]# cp /usr/local/redis-6.2.6/redis.conf /usr/local/redis/bin/</strong></p><p>修改 redis.conf 文件，把 daemonize no 改为 daemonize yes</p><p><strong>[root@localhost bin]# vi redis.conf</strong></p><p>后台启动</p><p><strong>[root@localhost bin]# ./redis-server redis.conf</strong></p><p>六、设置开机启动</p><p>添加开机启动服务</p><p><strong>[root@localhost bin]# vi /etc/systemd/system/redis.service</strong></p><p>复制粘贴以下内容：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description=redis-server</span></span>
<span class="line"><span>After=network.target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>Type=forking</span></span>
<span class="line"><span>ExecStart=/usr/local/redis/bin/redis-server /usr/local/redis/bin/redis.conf</span></span>
<span class="line"><span>PrivateTmp=true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy=multi-user.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>注意：ExecStart配置成自己的路径</p><p>设置开机启动</p><p><strong>[root@localhost bin]# systemctl daemon-reload</strong></p><p><strong>[root@localhost bin]# systemctl start redis.service</strong></p><p><strong>[root@localhost bin]# systemctl enable redis.service</strong></p><p>创建 redis 命令软链接</p><p><strong>[root@localhost ~]# ln -s /usr/local/redis/bin/redis-cli /usr/bin/redis</strong></p><p>测试 redis</p><p>服务操作命令</p><p>systemctl start redis.service #启动redis服务</p><p>systemctl stop redis.service #停止redis服务</p><p>systemctl restart redis.service #重新启动服务</p><p>systemctl status redis.service #查看服务当前状态</p><p>systemctl enable redis.service #设置开机自启动</p><p>systemctl disable redis.service #停止开机自启动</p>`,42)])])}const m=e(p,[["render",t]]);export{b as __pageData,m as default};
